#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while(t--) {        int n;        char c;        cin >> n >> c;         string s;        cin >> s;         if(c == 'g') {            cout << 0 << "\n";            continue;        }         string t = s + s;        int m = t.size();         vector<int> nextG(m, 1e9);         int last = 1e9;         for(int i = m-1; i >= 0; i--) {            if(t[i] == 'g')                last = i;            nextG[i] = last;        }         int ans = 0;         for(int i = 0; i < n; i++) {            if(s[i] == c) {                ans = max(ans, nextG[i] - i);            }        }         cout << ans << "\n";    }}